$ErrorActionPreference = 'Stop'
$version = & (Join-Path $PSScriptRoot 'Get-BuildVersion.ps1')

$text = @"
// This file is generated by update-version.ps1

using System.Reflection;

[assembly: AssemblyVersion("$($version.AssemblyVersion)")]
[assembly: AssemblyInformationalVersion("$($version.InformationalVersion)")]
"@

$versionFile = Join-Path (Split-Path -Parent $PSScriptRoot) 'GitVersion.cs'
if (!(Test-Path -LiteralPath $versionFile) -or
    [IO.File]::ReadAllText($versionFile) -ne $text) {
    [IO.File]::WriteAllText($versionFile, $text, [Text.UTF8Encoding]::new($false))
}
